import { test } from "node:test";
import assert from "node:assert/strict";
import { setImmediate as tick } from "node:timers/promises";
import { RestCarrier, SoapCarrier, type SoapRateClient, type Transport } from "../src/shipping/carriers.ts";
import { NoRatesError, RateShopper } from "../src/shipping/rateShop.ts";
import { TimeoutError, withTimeout } from "../src/shipping/timeout.ts";

// HTTP transport fake that answers after `delayMs` (or fails), and honours the abort signal like fetch().
function transport(amount: string, days: number, opts: { delayMs?: number; fail?: string } = {}): Transport & { aborted: boolean } {
    const t = Object.assign(
        (_path: string, _body: unknown, signal: AbortSignal) =>
            new Promise<unknown>((resolve, reject) => {
                const done = () => (opts.fail ? reject(new Error(opts.fail)) : resolve({ rate: { amount, transit_days: days } }));
                if (!opts.delayMs) return void tick().then(done);
                const timer = setTimeout(done, opts.delayMs);
                signal.addEventListener("abort", () => {
                    t.aborted = true;
                    clearTimeout(timer);
                    reject(signal.reason);
                });
            }),
        { aborted: false },
    );
    return t;
}

// Vendor SDK fake. When `hang` is set the callback is never called (the vendor's server stopped answering).
function soapClient(charge: number, days: number, hang = false): SoapRateClient {
    return {
        getRate(_req, cb) {
            if (!hang) void tick().then(() => cb(null, { TotalCharge: charge, Days: days }));
        },
    };
}

async function within<T>(ms: number, work: Promise<T>): Promise<T> {
    let timer: NodeJS.Timeout | undefined;
    const timeout = new Promise<never>((_, reject) => {
        timer = setTimeout(() => reject(new Error(`checkout still waiting after ${ms}ms`)), ms);
    });
    try {
        return await Promise.race([work, timeout]);
    } finally {
        clearTimeout(timer);
    }
}

const parcel = { fromZip: "10001", toZip: "94105", weightGrams: 2300, service: "ground" as const };

test("the cheapest carrier wins, faster transit breaking ties", async () => {
    const shopper = new RateShopper([
        new RestCarrier("ParcelCo", transport("14.20", 5)),
        new RestCarrier("ShipFast", transport("11.90", 4)),
        new SoapCarrier("Midwest Freight", soapClient(11.9, 3)),
    ], 40);
    const result = await within(500, shopper.shop(parcel));
    assert.deepEqual(result.best, { carrier: "Midwest Freight", priceCents: 1190, transitDays: 3 });
    assert.deepEqual(result.quotes.map((q) => q.carrier), ["Midwest Freight", "ShipFast", "ParcelCo"]);
    assert.deepEqual(result.skipped, []);
});

test("a slow HTTP carrier is skipped and its request is cancelled", async () => {
    const slow = transport("9.00", 2, { delayMs: 300 });
    const shopper = new RateShopper([new RestCarrier("ParcelCo", transport("14.20", 5)), new RestCarrier("ShipFast", slow)], 30);
    const result = await within(500, shopper.shop(parcel));
    assert.equal(result.best.carrier, "ParcelCo");
    assert.deepEqual(result.skipped.map((s) => [s.carrier, s.reason]), [["ShipFast", "timeout"]]);
    assert.equal(slow.aborted, true);
});

test("a carrier that errors is skipped as an error", async () => {
    const shopper = new RateShopper([new RestCarrier("ParcelCo", transport("0", 0, { fail: "503 Service Unavailable" })), new SoapCarrier("Midwest Freight", soapClient(16.5, 2))], 30);
    const result = await within(500, shopper.shop(parcel));
    assert.equal(result.best.priceCents, 1650);
    assert.deepEqual(result.skipped, [{ carrier: "ParcelCo", reason: "error", message: "503 Service Unavailable" }]);
});

test("a carrier whose SDK never answers doesn't hold up checkout", async () => {
    const shopper = new RateShopper([new RestCarrier("ShipFast", transport("11.90", 4)), new SoapCarrier("Midwest Freight", soapClient(0, 0, true))], 30);
    const result = await within(500, shopper.shop(parcel)).catch((err) => {
        console.log("rate shopping did not finish:", (err as Error).message);
        throw err;
    });
    assert.equal(result.best.carrier, "ShipFast");
    assert.deepEqual(result.skipped.map((s) => [s.carrier, s.reason]), [["Midwest Freight", "timeout"]]);
});

test("withTimeout gives up on work that ignores the abort signal", async () => {
    const never = () => new Promise<string>(() => {});
    await assert.rejects(within(500, withTimeout("label printer", 20, never)), (err: unknown) => {
        assert.ok(err instanceof TimeoutError, String(err));
        assert.equal(err.message, "label printer timed out after 20ms");
        return true;
    });
});

test("withTimeout passes results and errors straight through", async () => {
    assert.equal(await withTimeout("fast", 1000, async () => "ok"), "ok");
    await assert.rejects(withTimeout("broken", 1000, async () => { throw new Error("bad zip"); }), /bad zip/);
});

test("when no carrier answers in time checkout gets NoRatesError naming each one", async () => {
    const shopper = new RateShopper([new RestCarrier("ShipFast", transport("9", 1, { delayMs: 300 })), new SoapCarrier("Midwest Freight", soapClient(0, 0, true))], 25);
    await assert.rejects(within(500, shopper.shop(parcel)), (err: unknown) => {
        assert.ok(err instanceof NoRatesError, String(err));
        assert.deepEqual(err.skipped.map((s) => s.reason), ["timeout", "timeout"]);
        return true;
    });
});
